(()=>{
 const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));let stop=null,current=null,generation=0;
 window.productCareMarkup=p=>`${p.reviewEnabled===false?'':`<section class="detail-reviews product-care" id="detail-reviews"><h3>구매 고객 리뷰</h3><div id="product-review-list">리뷰를 불러오는 중입니다.</div><div id="product-review-write"></div></section>`}${p.qnaEnabled===false?'':`<section class="product-care" id="detail-qna"><h3>상품 Q&amp;A</h3><div id="product-qna-list">문의를 불러오는 중입니다.</div><div id="product-qna-write"></div></section>`}`;
 function forms(p){const user=window.moodnoteUser,review=document.getElementById('product-review-write'),qna=document.getElementById('product-qna-write'),orders=(window.moodnoteOrders||[]).filter(o=>['결제 완료','배송 준비','배송 중','배송 완료'].includes(o.status)&&o.items?.some(i=>i.id===p.id));if(review)review.innerHTML=orders.length?`<details><summary>구매 리뷰 작성</summary><form id="product-review-form"><label>구매 주문<select name="orderId">${orders.map(o=>`<option value="${esc(o.id)}">${esc(o.id)}</option>`).join('')}</select></label><label>평점<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n}점</option>`).join('')}</select></label><label>리뷰 내용<textarea name="text" required maxlength="2000" rows="4" placeholder="사용해본 느낌을 알려주세요."></textarea></label><button class="solid-button" type="submit">리뷰 등록</button></form></details>`:'<p>로그인 후 구매한 상품의 리뷰를 작성할 수 있습니다.</p>';if(qna)qna.innerHTML=user?'<details><summary>상품 문의 작성</summary><form id="product-qna-form"><label>제목<input name="title" required maxlength="120"/></label><label>내용<textarea name="content" required maxlength="2000" rows="4"></textarea></label><label class="care-check"><input name="secret" type="checkbox" checked/> 비밀글로 작성</label><button class="solid-button" type="submit">문의 등록</button></form></details>':'<p>로그인하면 상품에 대해 문의할 수 있습니다.</p>';}
 window.startProductCare=p=>{stop?.();stop=null;current=p;const token=++generation;forms(p);if(!window.moodnoteData?.watchProductCare)return;stop=window.moodnoteData.watchProductCare(p.id,result=>{if(token!==generation)return;if(result.error){['product-review-list','product-qna-list'].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent='정보를 불러오지 못했습니다. 잠시 후 다시 확인해주세요.';});return;}const reviews=result.reviews||[],qna=result.qna||[],reviewEl=document.getElementById('product-review-list'),qnaEl=document.getElementById('product-qna-list');document.querySelectorAll('[data-live-review-count]').forEach(el=>el.textContent=reviews.length+'개');if(reviewEl)reviewEl.innerHTML=reviews.length?reviews.map(r=>`<article class="care-entry"><header><strong>${esc(r.customer)}</strong><span>${'★'.repeat(Math.min(5,Math.max(1,Number(r.rating)||1)))}</span>${r.verifiedPurchase?'<small>구매 인증</small>':''}</header><p>${esc(r.text)}</p>${r.image?`<img src="${esc(r.image)}" alt="리뷰 사진" loading="lazy"/>`:''}${r.reply?`<div class="care-answer"><b>무드노트 답변</b><p>${esc(r.reply)}</p></div>`:''}</article>`).join(''):'<p>아직 등록된 리뷰가 없습니다. 첫 사용 후기를 남겨주세요.</p>';if(qnaEl)qnaEl.innerHTML=qna.length?qna.map(q=>`<details class="care-entry"><summary>${q.secret?'[비밀글] ':''}${esc(q.title)} · ${q.answer?'답변 완료':'답변 대기'}</summary><p>${esc(q.content)}</p>${q.answer?`<div class="care-answer"><b>무드노트 답변</b><p>${esc(q.answer)}</p></div>`:''}</details>`).join(''):'<p>등록된 상품 문의가 없습니다.</p>';});};
 for(const event of ['moodnote-data-ready','moodnote-auth-change'])window.addEventListener(event,()=>{if(current&&location.hash==='#product/'+current.id)window.startProductCare(current)});
 window.addEventListener('moodnote-orders',()=>{if(current&&location.hash==='#product/'+current.id)forms(current)});
 window.addEventListener('hashchange',()=>{if(current&&location.hash!=='#product/'+current.id){generation++;stop?.();stop=null;current=null;}});
 document.addEventListener('submit',async e=>{const form=e.target;if(!['product-review-form','product-qna-form'].includes(form.id))return;e.preventDefault();const button=e.submitter;button.disabled=true;try{if(!window.moodnoteUser)throw Error('로그인 후 작성해주세요.');const d=Object.fromEntries(new FormData(form));if(form.id==='product-review-form')await window.moodnoteData.createReview({...d,productId:current.id});else await window.moodnoteData.createQna({...d,secret:form.elements.secret.checked,productId:current.id,product:current.name});form.reset();toast('등록했습니다.');}catch(error){toast(error.message||'등록하지 못했습니다.');}finally{button.disabled=false;}});
})();
